/**
 * Hermes 小鲸鱼余额挂件 — hermes-whale-widget
 *
 * 移植自 DSH 插件 dsh-whale-widget（MeteorNOX，MIT）：
 *   https://github.com/MeteorNOX/DeepSeek-Balance-Whale-Widget
 * 上游是 DeepSeek Harness 的宿主侧插件 + 页面注入脚本；这里是 Hermes 桌面版
 * 插件 SDK 的等价实现（单文件、热重载、无独立进程）。
 *
 * 功能
 *   - 状态栏常驻鲸鱼：余额 / 今日已用 / 本轮消耗，点击手动刷新
 *   - 挂件面板：余额、今日已用（余额差值记账）、本轮消耗、峰谷时段、设置
 *   - 聊天内 ::whale 指令：把鲸鱼卡片画进对话里
 *   - 每轮对话消耗提醒（可选，默认关闭）
 *
 * 数据来源
 *   - 余额：https://api.deepseek.com/user/balance（DeepSeek 官方接口，需 sk- key）
 *   - 今日已用：本地记账 —— 每次观测余额后按差值累计（只有下降才算消费）
 *   - 本轮消耗：Hermes 会话 usage（tokens / cost_usd）
 *
 * 安装：把本文件复制到 $HERMES_HOME/desktop-plugins/whale-widget/plugin.js
 *      （Windows 默认 C:\Users\<你>\AppData\Local\hermes\desktop-plugins\），
 *      Hermes 桌面端会自动加载；改动保存后热重载。
 *
 * 加载面：仅 @hermes/plugin-sdk、react、react/jsx-runtime；文件不编译，用 jsx() 而不是 JSX 语法。
 */

import {
  atom,
  Button,
  cn,
  haptic,
  host,
  Input,
  PALETTE_AREA,
  STATUSBAR_AREAS,
  Switch,
  Tip,
  TRANSCRIPT_DIRECTIVE_AREA,
  usePluginI18n,
  useValue
} from '@hermes/plugin-sdk'
import { jsx, jsxs } from 'react/jsx-runtime'
import { useEffect, useState } from 'react'

const ID = 'whale-widget'

// 鲸鱼立绘（上游 assets/DSniang1.png，MIT）。由 scripts/set-whale-image.mjs 内联为 data URI，
// 换成自己的图后重跑脚本即可。别手改下面这一行。
const WHALE_PNG = 'data:image/png;base64,'

// ── 设置 ────────────────────────────────────────────────────────────────────

const KEY_SETTINGS = 'settings'
const KEY_LEDGER = 'ledger'

const DEFAULT_SETTINGS = {
  apiKey: '',
  baseUrl: 'https://api.deepseek.com',
  refreshSec: 60,
  lowBalance: 10,
  showChip: true,
  turnToast: false
}

const MIN_REFRESH_SEC = 15
const MAX_REFRESH_SEC = 3600

// DeepSeek 峰谷时段（北京时间）。工作日 9:00–12:00、14:00–18:00 为高峰，其余谷价；
// 2026-08-23 起周末全天按谷价。价格表随官方调整，这里只用它显示"当前处于哪一档"。
const PEAK_HOURS = [
  [9, 12],
  [14, 18]
]
const WEEKEND_VALLEY_FROM_SEC = Math.floor(Date.UTC(2026, 7, 22, 16, 0, 0) / 1000)

function isPeakNow(nowSec = Date.now() / 1000) {
  const n = Number(nowSec)
  if (!isFinite(n)) return false
  const bj = new Date(n * 1000 + 8 * 3600 * 1000) // 按 UTC 读 = 北京日历时间
  if (n >= WEEKEND_VALLEY_FROM_SEC) {
    const dow = bj.getUTCDay()
    if (dow === 0 || dow === 6) return false
  }
  const hour = bj.getUTCHours()
  for (const [start, end] of PEAK_HOURS) {
    if (hour >= start && hour < end) return true
  }
  return false
}

// ── 原子状态（模块级：所有挂件面共享一份）─────────────────────────────────────

const $settings = atom({ ...DEFAULT_SETTINGS })
const $ledger = atom({ date: '', currency: '', last: null, spent: 0 })
const $status = atom({ state: 'idle', code: '', message: '', at: 0 }) // state: idle|loading|ok|error
const $balance = atom(null) // { currency, total, granted, topped, available, today }
const $lastTurn = atom(null) // { tokens, costUsd, at }
const $liveTurn = atom(null) // 进行中本轮 { tokens, costUsd }

// register() 里注入的持久化句柄（ctx.storage 是插件命名空间的 JSON 存储）
let save = () => {}
let load = (key, fallback) => fallback

// ── 余额观测 + 记账 ─────────────────────────────────────────────────────────

function localDateKey(d = new Date()) {
  const p = n => String(n).padStart(2, '0')
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`
}

async function fetchBalance(settings) {
  if (!settings.apiKey) {
    const err = new Error('NO_KEY')
    err.code = 'NO_KEY'
    throw err
  }
  const base = String(settings.baseUrl || DEFAULT_SETTINGS.baseUrl).replace(/\/+$/, '')
  const res = await fetch(`${base}/user/balance`, {
    cache: 'no-store',
    headers: { Authorization: `Bearer ${settings.apiKey}` }
  })
  if (!res.ok) {
    const err = new Error(`HTTP ${res.status}`)
    err.code = `HTTP_${res.status}`
    throw err
  }
  const data = await res.json()
  const info = Array.isArray(data && data.balance_infos) ? data.balance_infos[0] : null
  if (!info) {
    const err = new Error('NO_BALANCE_INFO')
    err.code = 'NO_BALANCE_INFO'
    throw err
  }
  return {
    available: data.is_available !== false,
    currency: String(info.currency || 'CNY'),
    total: Number(info.total_balance),
    granted: Number(info.granted_balance || 0),
    topped: Number(info.topped_up_balance || 0)
  }
}

/**
 * 余额差值记账（上游「小鲸鱼记账」的等价实现）：
 * 跨天重置基准；币种变化只重置基准不记差值（避免 CNY↔USD 跳变记出假账，上游 #13）；
 * 只有余额下降才算消费（充值不会记成负支出）。
 */
function applyLedger(prev, snapshot) {
  const date = localDateKey()
  let next = prev && typeof prev === 'object' ? { ...prev } : { date: '', currency: '', last: null, spent: 0 }
  if (next.date !== date) {
    next = { date, currency: snapshot.currency, last: snapshot.total, spent: 0 }
  } else if (next.currency !== snapshot.currency || typeof next.last !== 'number') {
    // 币种切换 / 旧账本缺字段：整本重置。宁可少记，也不把两种币种的差额加在一起
    // （上游 #13 的假账根因就是 CNY↔USD 跳变被当成消费）。
    next = { date, currency: snapshot.currency, last: snapshot.total, spent: 0 }
  } else if (snapshot.total < next.last) {
    next.spent = Math.round((next.spent + (next.last - snapshot.total)) * 1e6) / 1e6
    next.last = snapshot.total
  } else {
    next.last = snapshot.total
  }
  return next
}

function persistLedger(ledger) {
  $ledger.set(ledger)
  save(KEY_LEDGER, ledger)
}

async function observe() {
  const settings = $settings.get()
  $status.set({ ...$status.get(), state: 'loading', code: '', message: '' })
  try {
    const snapshot = await fetchBalance(settings)
    const ledger = applyLedger($ledger.get(), snapshot)
    persistLedger(ledger)
    const payload = { ...snapshot, today: ledger.spent }
    $balance.set(payload)
    $status.set({ state: 'ok', code: '', message: '', at: Date.now() })
    return payload
  } catch (err) {
    // 瞬时抖动沿用最近一次余额，不把 UI 打回空值（上游同款行为）
    $status.set({
      state: 'error',
      code: String((err && err.code) || 'ERROR'),
      message: String((err && err.message) || err),
      at: Date.now()
    })
    return null
  }
}

// ── 轮询（单例：与挂件是否可见无关，插件启用就在跑）──────────────────────────

let timer = null
let unlistenSettings = null

function startPolling() {
  const restart = () => {
    if (timer) clearInterval(timer)
    const sec = Math.min(MAX_REFRESH_SEC, Math.max(MIN_REFRESH_SEC, Number($settings.get().refreshSec) || 60))
    timer = setInterval(() => void observe(), sec * 1000)
  }
  restart()
  if (!unlistenSettings) unlistenSettings = $settings.listen(restart)
  void observe()
}

// ── 每轮对话消耗：按会话分桶，避免主会话与子代理并行时串账 ────────────────────

function initTurnTracking() {
  const snapshot = new Map() // sessionId -> { tokens, costUsd }
  let wasBusy = false

  const readFocus = () => {
    try {
      return {
        id: host.state.focusedSessionId.get() || 'default',
        usage: host.state.focusedUsage.get() || null
      }
    } catch (_err) {
      return { id: 'default', usage: null }
    }
  }

  // 结算：返回相对上次快照的增量，并把快照推到当前值
  const settle = (id, usage) => {
    if (!usage) return null
    const tokens = Number(usage.total || 0)
    const costUsd = Number(usage.cost_usd || 0)
    const prev = snapshot.get(id)
    snapshot.set(id, { tokens, costUsd })
    if (!prev) return null
    return { tokens: Math.max(0, tokens - prev.tokens), costUsd: Math.max(0, costUsd - prev.costUsd) }
  }

  const sample = () => {
    const { id, usage } = readFocus()
    const delta = settle(id, usage)
    if (delta && (delta.tokens || delta.costUsd)) $liveTurn.set(delta)
  }

  const finalize = () => {
    const { id, usage } = readFocus()
    let turn = $liveTurn.get()
    const delta = settle(id, usage)
    if (!turn && delta && (delta.tokens || delta.costUsd)) turn = delta
    $liveTurn.set(null)
    if (!turn) return
    const settled = { ...turn, at: Date.now() }
    $lastTurn.set(settled)
    if ($settings.get().turnToast) {
      const today = $balance.get()
      host.notify({
        kind: 'info',
        message: `🐳 本轮消耗 $${settled.costUsd.toFixed(4)} · ${settled.tokens.toLocaleString()} tokens${
          today && typeof today.today === 'number' ? ` · 今日 ¥${today.today.toFixed(2)}` : ''
        }`
      })
    }
  }

  const disposers = []
  try {
    if (typeof host.state.focusedUsage.listen === 'function') {
      disposers.push(host.state.focusedUsage.listen(() => sample()))
    }
    if (typeof host.state.busy.listen === 'function') {
      disposers.push(
        host.state.busy.listen(busy => {
          if (busy) sample()
          else if (wasBusy) finalize()
          wasBusy = Boolean(busy)
        })
      )
    }
  } catch (_err) {
    /* 老版本没有原子 listen：下面的事件流兜底 */
  }
  try {
    disposers.push(host.onEvent('message.complete', () => finalize()))
  } catch (_err) {
    /* 事件流不可用就只有原子订阅 */
  }
  return () => {
    for (const d of disposers) {
      try {
        d()
      } catch (_err) {}
    }
  }
}

// ── 展示辅助 ────────────────────────────────────────────────────────────────

function money(value) {
  if (value === null || value === undefined || !isFinite(Number(value))) return '--'
  const n = Number(value)
  return n.toFixed(Math.abs(n) < 10 ? 2 : 2)
}

function hhmm(ts) {
  if (!ts) return ''
  const d = new Date(ts)
  const p = n => String(n).padStart(2, '0')
  return `${p(d.getHours())}:${p(d.getMinutes())}`
}

function chipText(t, settings, balance, status, ledger) {
  if (status.state === 'error') {
    const code = status.code
    if (code === 'NO_KEY') return t('chipNoKey')
    return t('chipError')
  }
  if (!settings.apiKey) return t('chipNoKey')
  if (!balance) return '🐳 --'
  return `🐳 ${balance.currency === 'CNY' ? '¥' : ''}${money(balance.total)}`
}

// ── 状态栏挂件 ──────────────────────────────────────────────────────────────

function WhaleChip() {
  const t = usePluginI18n(ID)
  const settings = useValue($settings)
  const balance = useValue($balance)
  const status = useValue($status)
  const ledger = useValue($ledger)
  const lastTurn = useValue($lastTurn)

  if (!settings.showChip) return null

  const pending = status.state === 'loading'
  const low = balance && isFinite(balance.total) && balance.total <= Number(settings.lowBalance || 0)
  const tip = [
    balance ? t('tipBalance', balance.currency === 'CNY' ? '¥' : '', money(balance.total)) : t('tipNoBalance'),
    t('tipToday', ledger.currency === 'CNY' ? '¥' : '', money(ledger.spent)),
    lastTurn ? t('tipTurn', lastTurn.costUsd.toFixed(4), lastTurn.tokens.toLocaleString()) : '',
    t('tipPeak', isPeakNow() ? t('peak') : t('valley')),
    status.at ? t('tipUpdated', hhmm(status.at)) : '',
    status.state === 'error' ? t('tipError', status.code) : '',
    t('tipRefresh')
  ]
    .filter(Boolean)
    .join(' · ')

  return jsx(Tip, {
    label: tip,
    children: jsx('button', {
      type: 'button',
      onClick: () => {
        haptic('tap')
        void observe()
      },
      className: cn(
        'inline-flex h-full items-center gap-1 px-1.5 text-[0.6875rem] transition-colors',
        'text-(--ui-text-tertiary) hover:bg-(--chrome-action-hover) hover:text-foreground'
      ),
      children: [
        jsx('span', { children: chipText(t, settings, balance, status, ledger) }),
        low ? jsx('span', { className: 'text-(--ui-accent)', children: '低' }) : null,
        pending ? jsx('span', { children: '…' }) : null
      ].filter(Boolean)
    })
  })
}

// ── 台词（随日期与余额变化，不跑定时器）───────────────────────────────────────

function quip(t, balance) {
  const lines = [t('quip1'), t('quip2'), t('quip3'), t('quip4')]
  const seed = (localDateKey().split('-').join('') | 0) + (balance ? Math.round(balance.total * 100) : 0)
  return lines[Math.abs(seed) % lines.length]
}

// ── 挂件面板 ────────────────────────────────────────────────────────────────

function StatRow({ t, label, value, hint }) {
  return jsxs('div', {
    className: 'flex items-baseline justify-between gap-2',
    children: [
      jsx('span', { className: 'text-(--ui-text-tertiary)', children: label }),
      jsxs('span', {
        className: 'flex items-baseline gap-2',
        children: [
          jsx('span', { className: 'tabular-nums', children: value }),
          hint ? jsx('span', { className: 'text-[0.625rem] text-(--ui-text-quaternary)', children: hint }) : null
        ].filter(Boolean)
      })
    ]
  })
}

function WhalePane() {
  const t = usePluginI18n(ID)
  const settings = useValue($settings)
  const balance = useValue($balance)
  const ledger = useValue($ledger)
  const status = useValue($status)
  const lastTurn = useValue($lastTurn)
  const liveTurn = useValue($liveTurn)

  const [keyDraft, setKeyDraft] = useState(settings.apiKey)
  const [keyNote, setKeyNote] = useState('')
  const [refreshDraft, setRefreshDraft] = useState(String(settings.refreshSec))
  const [lowDraft, setLowDraft] = useState(String(settings.lowBalance))

  useEffect(() => {
    setKeyDraft(settings.apiKey)
    setRefreshDraft(String(settings.refreshSec))
    setLowDraft(String(settings.lowBalance))
  }, [settings.apiKey, settings.refreshSec, settings.lowBalance])

  const update = patch => {
    const next = { ...$settings.get(), ...patch }
    $settings.set(next)
    save(KEY_SETTINGS, next)
  }

  // 从 Hermes 自己的 config.yaml 读 custom_providers 里的 DeepSeek key，省得手输。
  const importKey = async () => {
    try {
      const res = await host.request('config.get', { key: 'full' })
      const cfg = (res && res.config) || res || {}
      const providers = Array.isArray(cfg.custom_providers) ? cfg.custom_providers : []
      const hit = providers.find(p => String((p && p.base_url) || '').includes('deepseek'))
      const key = String((hit && hit.api_key) || '').trim()
      if (!/^sk-/.test(key)) {
        setKeyNote(t('importFail'))
        return
      }
      update({ apiKey: key })
      setKeyNote(t('importOk', key.slice(0, 6), key.slice(-4)))
      void observe()
    } catch (_err) {
      setKeyNote(t('importFail'))
    }
  }

  const peak = isPeakNow()
  const low = balance && isFinite(balance.total) && balance.total <= Number(settings.lowBalance || 0)
  const turn = liveTurn || lastTurn

  const statusLine = (() => {
    if (status.state === 'loading') return t('loading')
    if (status.state === 'error') return t('errorLine', status.code)
    if (status.at) return t('updated', hhmm(status.at))
    return t('never')
  })()

  return jsxs('div', {
    className: 'flex h-full flex-col gap-3 overflow-auto p-3 text-xs',
    children: [
      jsxs('div', {
        className: 'flex items-end gap-3',
        children: [
          jsx('img', {
            src: WHALE_PNG,
            alt: 'whale',
            onClick: () => {
              haptic('tap')
              void observe()
            },
            className: 'h-20 w-20 shrink-0 cursor-pointer select-none',
            title: t('clickRefresh')
          }),
          jsxs('div', {
            className: 'flex min-w-0 flex-col gap-0.5',
            children: [
              jsx('div', { className: 'text-[0.625rem] text-(--ui-text-tertiary)', children: t('paneTitle') }),
              jsx('div', {
                className: cn('text-2xl leading-tight tabular-nums', low && 'text-(--ui-accent)'),
                children: balance ? `${balance.currency === 'CNY' ? '¥' : ''}${money(balance.total)}` : '--'
              }),
              jsx('div', { className: 'truncate text-[0.625rem] text-(--ui-text-quaternary)', children: statusLine })
            ]
          })
        ]
      }),

      jsx('div', {
        className: 'text-[0.6875rem] text-(--ui-text-quaternary)',
        children: quip(t, balance)
      }),

      jsxs('div', {
        className: 'flex flex-col gap-1',
        children: [
          jsx(StatRow, {
            t,
            label: t('todaySpent'),
            value: `${ledger.currency === 'CNY' ? '¥' : ''}${money(ledger.spent)}`,
            hint: t('ledgerHint')
          }),
          jsx(StatRow, {
            t,
            label: t('lastTurn'),
            value: turn ? `$${Number(turn.costUsd || 0).toFixed(4)}` : '--',
            hint: turn ? t('turnTokens', Number(turn.tokens || 0).toLocaleString(), turn.at ? hhmm(turn.at) : '') : ''
          }),
          jsx(StatRow, {
            t,
            label: t('rate'),
            value: peak ? t('peak') : t('valley'),
            hint: t('rateHint')
          })
        ]
      }),

      jsxs('div', {
        className: 'flex items-center gap-2',
        children: [
          jsx(Button, {
            size: 'sm',
            variant: 'secondary',
            onClick: () => {
              haptic('tap')
              void observe()
            },
            children: t('refreshNow')
          }),
          jsx('span', { className: 'text-[0.625rem] text-(--ui-text-quaternary)', children: t('apiKeyHint') })
        ]
      }),

      jsxs('div', {
        className: 'flex flex-col gap-2 border-t border-(--ui-stroke-secondary) pt-3',
        children: [
          jsx('div', { className: 'text-[0.625rem] font-medium text-(--ui-text-tertiary)', children: t('settings') }),

          jsx('div', {
            className: 'flex gap-2',
            children: [
              jsx(Input, {
                type: 'password',
                value: keyDraft,
                placeholder: 'sk-…',
                onChange: e => setKeyDraft(e.target.value),
                className: 'h-7 text-xs'
              }),
              jsx(Button, {
                size: 'sm',
                variant: 'secondary',
                onClick: () => {
                  update({ apiKey: keyDraft.trim() })
                  setKeyNote('')
                  void observe()
                },
                children: t('save')
              })
            ]
          }),
          jsxs('div', {
            className: 'flex items-center gap-2',
            children: [
              jsx(Button, {
                size: 'sm',
                variant: 'ghost',
                onClick: () => void importKey(),
                children: t('importKey')
              }),
              jsx('span', { className: 'truncate text-[0.625rem] text-(--ui-text-quaternary)', children: keyNote })
            ]
          }),

          jsxs('div', {
            className: 'flex items-center justify-between gap-2',
            children: [
              jsx('span', { children: t('refreshSec') }),
              jsx(Input, {
                type: 'number',
                min: MIN_REFRESH_SEC,
                max: MAX_REFRESH_SEC,
                value: refreshDraft,
                onChange: e => setRefreshDraft(e.target.value),
                onBlur: () =>
                  update({
                    refreshSec: Math.min(MAX_REFRESH_SEC, Math.max(MIN_REFRESH_SEC, Number(refreshDraft) || 60))
                  }),
                className: 'h-7 w-20 text-xs'
              })
            ]
          }),

          jsxs('div', {
            className: 'flex items-center justify-between gap-2',
            children: [
              jsx('span', { children: t('lowBalance') }),
              jsx(Input, {
                type: 'number',
                min: 0,
                value: lowDraft,
                onChange: e => setLowDraft(e.target.value),
                onBlur: () => update({ lowBalance: Math.max(0, Number(lowDraft) || 0) }),
                className: 'h-7 w-20 text-xs'
              })
            ]
          }),

          jsxs('label', {
            className: 'flex items-center justify-between gap-2',
            children: [
              jsx('span', { children: t('showChip') }),
              jsx(Switch, { checked: settings.showChip, onCheckedChange: v => update({ showChip: Boolean(v) }) })
            ]
          }),

          jsxs('label', {
            className: 'flex items-center justify-between gap-2',
            children: [
              jsx('span', { children: t('turnToast') }),
              jsx(Switch, { checked: settings.turnToast, onCheckedChange: v => update({ turnToast: Boolean(v) }) })
            ]
          })
        ]
      })
    ]
  })
}

// ── 聊天内 ::whale 指令 ─────────────────────────────────────────────────────

function WhaleDirective() {
  const t = usePluginI18n(ID)
  const balance = useValue($balance)
  const ledger = useValue($ledger)

  return jsxs('div', {
    className: 'flex items-end gap-3 py-1 text-xs',
    children: [
      jsx('img', { src: WHALE_PNG, alt: 'whale', className: 'h-14 w-14 shrink-0 select-none' }),
      jsxs('div', {
        className: 'flex flex-col gap-0.5',
        children: [
          jsx('div', {
            className: 'text-base leading-tight tabular-nums',
            children: balance ? `余额 ${balance.currency === 'CNY' ? '¥' : ''}${money(balance.total)}` : t('tipNoBalance')
          }),
          jsx('div', {
            className: 'text-(--ui-text-quaternary)',
            children: `${t('todaySpent')} ${ledger.currency === 'CNY' ? '¥' : ''}${money(ledger.spent)} · ${
              isPeakNow() ? t('peak') : t('valley')
            }`
          })
        ]
      })
    ]
  })
}

